import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
import unittest
from http.client import HTTPConnection
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote

MAX_BODY = 1024 * 1024
MISSING = object()


class Store:
    def __init__(self, filename: str):
        self.path = Path(filename)
        self.lock = threading.RLock()
        self.entries: dict[str, dict] = {}
        self._load()

    def _load(self) -> None:
        try:
            with self.path.open(encoding="utf-8") as source:
                raw = json.load(source)
            if not isinstance(raw, dict):
                raise ValueError("top-level data is not an object")
            for key, entry in raw.items():
                if isinstance(key, str) and isinstance(entry, dict) and "value" in entry:
                    expiry = entry.get("expires_at")
                    if expiry is None or (isinstance(expiry, (int, float)) and math.isfinite(expiry)):
                        self.entries[key] = {"value": entry["value"], "expires_at": expiry}
        except FileNotFoundError:
            return
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            print(f"warning: cannot load data file: {exc}", file=sys.stderr, flush=True)
        self._purge_locked(persist=False)

    def _purge_locked(self, persist: bool = True) -> bool:
        now = time.time()
        dead = [key for key, entry in self.entries.items()
                if entry["expires_at"] is not None and entry["expires_at"] <= now]
        for key in dead:
            del self.entries[key]
        if dead and persist:
            self._save_locked()
        return bool(dead)

    def _save_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = json.dumps(self.entries, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
        fd, temp_name = tempfile.mkstemp(prefix=f".{self.path.name}.", suffix=".tmp", dir=self.path.parent)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as target:
                target.write(payload)
                target.flush()
                os.fsync(target.fileno())
            os.replace(temp_name, self.path)
        except Exception:
            try:
                os.unlink(temp_name)
            except FileNotFoundError:
                pass
            raise

    def get(self, key: str):
        with self.lock:
            self._purge_locked()
            entry = self.entries.get(key)
            return MISSING if entry is None else entry["value"]

    def put(self, key: str, value, ttl: float | None) -> bool:
        with self.lock:
            self._purge_locked()
            created = key not in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else time.time() + ttl}
            self._save_locked()
            return created

    def delete(self, key: str) -> bool:
        with self.lock:
            self._purge_locked()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save_locked()
            return True

    def keys(self) -> list[str]:
        with self.lock:
            self._purge_locked()
            return sorted(self.entries)


def route_key(path: str) -> str | None:
    prefix = "/v1/kv/"
    if not path.startswith(prefix):
        return None
    encoded = path[len(prefix):]
    if not encoded or "/" in encoded:
        return None
    try:
        key = unquote(encoded, encoding="utf-8", errors="strict")
    except UnicodeDecodeError:
        return None
    return key if key and "/" not in key else None


